import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";

const NavBar = (props) => {
    const { theme = 'dark', onToggleTheme = () => { } } = props;
    const [temp, setTemp] = useState(null);
    const [status, setStatus] = useState("...");
    const [dateStr, setDateStr] = useState("");
    const [timeStr, setTimeStr] = useState("");

    // DATE + TIME
    useEffect(() => {
        const updateTime = () => {
            const now = new Date();
            setDateStr(now.toLocaleDateString("en-US"));
            setTimeStr(
                now.toLocaleTimeString("en-US", {
                    hour: "2-digit",
                    minute: "2-digit",
                })
            );
        };
        updateTime();
        const interval = setInterval(updateTime, 30000);
        return () => clearInterval(interval);
    }, []);

    // WEATHER
    useEffect(() => {
        if (!navigator.geolocation) {
            setStatus("NO-LOC");
            return;
        }

        navigator.geolocation.getCurrentPosition(
            async (pos) => {
                const lat = pos.coords.latitude;
                const lon = pos.coords.longitude;

                setStatus("OK");

                try {
                    const weatherRes = await fetch(
                        `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&current_weather=true`
                    );
                    const data = await weatherRes.json();
                    setTemp(Math.round(data.current_weather.temperature));
                } catch (error) {
                    setStatus("ERR");
                }
            },
            () => setStatus("DENIED")
        );
    }, []);

    const [searchQuery, setSearchQuery] = useState("");

    const handleSearch = (e) => {
        e.preventDefault();
        if (searchQuery.trim()) {
            if (props.onSearch) {
                props.onSearch(searchQuery);
            }
        }
    };

    return (
        <nav className="navbar fixed-top navbar-expand-lg navbar-dark bg-dark">
            <div className="container-fluid d-flex align-items-center">

                {/* LEFT - BRAND */}
                <Link className="navbar-brand" to="/">NewsMonkey</Link>

                {/* HAMBURGER */}
                <button className="navbar-toggler" type="button"
                    data-bs-toggle="collapse"
                    data-bs-target="#navbarSupportedContent">
                    <span className="navbar-toggler-icon"></span>
                </button>

                {/* NAV LINKS */}
                <div className="collapse navbar-collapse" id="navbarSupportedContent">
                    <ul className="navbar-nav me-auto mb-2 mb-lg-0">
                        <li className="nav-item"><Link className="nav-link" to="/">Home</Link></li>

                        <li className="nav-item dropdown">
                            <a className="nav-link dropdown-toggle" href="/" id="navbarDropdown" role="button" data-bs-toggle="dropdown" aria-expanded="false" onClick={(e) => e.preventDefault()}>
                                Categories
                            </a>
                            <ul className="dropdown-menu" aria-labelledby="navbarDropdown">
                                <li><Link className="dropdown-item" to="/business">Business</Link></li>
                                <li><Link className="dropdown-item" to="/entertainment">Entertainment</Link></li>
                                <li><Link className="dropdown-item" to="/general">General</Link></li>
                                <li><Link className="dropdown-item" to="/health">Health</Link></li>
                                <li><Link className="dropdown-item" to="/science">Science</Link></li>
                                <li><Link className="dropdown-item" to="/sports">Sports</Link></li>
                                <li><Link className="dropdown-item" to="/technology">Technology</Link></li>
                            </ul>
                        </li>
                    </ul>

                    {/* SEARCH BAR */}
                    <form className="search-form" onSubmit={handleSearch}>
                        <input
                            className="search-input"
                            type="search"
                            placeholder="Search news..."
                            aria-label="Search"
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                        />
                        <button className="search-btn" type="submit">
                            <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" fill="currentColor" className="bi bi-search" viewBox="0 0 16 16">
                                <path d="M11.742 10.344a6.5 6.5 0 1 0-1.397 1.398h-.001c.03.04.062.078.098.115l3.85 3.85a1 1 0 0 0 1.415-1.414l-3.85-3.85a1.007 1.007 0 0 0-.115-.1zM12 6.5a5.5 5.5 0 1 1-11 0 5.5 5.5 0 0 1 11 0z" />
                            </svg>
                        </button>
                    </form>
                </div>

                {/* RIGHT SIDE — ALWAYS FIXED RIGHT */}
                <div className="ms-auto d-flex align-items-center gap-3">
                    <button
                        className={`theme-toggle-btn ${theme === 'light' ? 'light' : ''}`}
                        type="button"
                        onClick={onToggleTheme}
                        aria-label="Toggle color theme"
                    >
                        {theme === 'dark' ? 'LIGHT MODE' : 'DARK MODE'}
                    </button>
                    <div className="retro-nav-info text-end">
                        <small>
                            {dateStr} | {timeStr}
                            {temp !== null ? ` | ${temp}°C` : ""}
                            {status !== "OK" && temp == null ? " | NO-TEMP" : ""}
                        </small>
                    </div>
                </div>

            </div>
        </nav>
    );
};

export default NavBar;
